-- Rook schema, migration 0002.
--
-- Adds the five capabilities that turn a working chat client into something a
-- community can actually be administered with:
--
--   * channel categories   -- sidebar structure
--   * read state + mentions -- unread badges that mean something
--   * member role changes   -- a role management surface needs somewhere to write
--   * invite links          -- sharing access without handing out a permanent code
--   * audit log             -- a record of who changed what
--
-- Conventions follow 0001: uuid keys generated by the application, timestamptz
-- in UTC, every text limit mirrored from the Zod schemas in @rook/contracts,
-- and every foreign key stating its delete behaviour explicitly.

-- ---------------------------------------------------------------------------
-- Channel categories
-- ---------------------------------------------------------------------------
--
-- A category is purely sidebar structure: it groups channels and carries a
-- collapse state on the client. It holds no permissions of its own, which is
-- why deleting one does not delete its channels -- see the FK below.

create table channel_categories (
  id            uuid primary key,
  community_id  uuid        not null references communities (id) on delete cascade,

  name          text        not null,
  position      integer     not null default 0,

  created_by    uuid        not null references users (id) on delete restrict,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),

  constraint channel_categories_name_length check (char_length(name) between 1 and 64),
  constraint channel_categories_position_non_negative check (position >= 0)
);

-- Two categories with the same name in one community would be indistinguishable.
create unique index channel_categories_community_name_key
  on channel_categories (community_id, name);

create index channel_categories_community_position_idx
  on channel_categories (community_id, position, id);

-- `set null`, not `cascade`: deleting a category must not delete the
-- conversations inside it. Orphaned channels fall back to the uncategorised
-- group at the top of the sidebar, which is recoverable; deleted history is not.
alter table channels
  add column category_id uuid references channel_categories (id) on delete set null;

-- Replaces channels_community_position_idx as the sidebar's read path: the
-- sidebar now orders by category first.
create index channels_community_category_position_idx
  on channels (community_id, category_id, position, id);

-- ---------------------------------------------------------------------------
-- Mentions
-- ---------------------------------------------------------------------------
--
-- Mentions are resolved once, when the message is written, and stored as rows.
-- The alternative -- scanning message text at read time to decide whether a
-- channel has an unread mention for you -- would mean reading every unread
-- message on every sidebar render.

alter table messages
  add column mentions_everyone boolean not null default false;

create table message_mentions (
  message_id  uuid not null references messages (id) on delete cascade,
  user_id     uuid not null references users (id) on delete cascade,

  -- Denormalised from the message so the unread query can count mentions per
  -- channel without joining back to messages.
  channel_id  uuid not null references channels (id) on delete cascade,

  primary key (message_id, user_id)
);

-- The unread-mention count path: "mentions of me in this channel after X".
create index message_mentions_user_channel_idx
  on message_mentions (user_id, channel_id, message_id);

-- ---------------------------------------------------------------------------
-- Read state
-- ---------------------------------------------------------------------------
--
-- One row per (user, channel), holding the last message the user has seen.
-- Unread counts are derived from it rather than stored, so a count can never
-- drift out of step with the messages it describes.
--
-- `last_read_message_id` is a plain uuid with no foreign key on purpose: the
-- id is used as a `> id` boundary in the unread query, and a cascade from a
-- hard-deleted message would silently reset someone's read position. Messages
-- are only ever soft-deleted, so the id stays valid as a boundary regardless.

create table channel_read_state (
  user_id               uuid        not null references users (id) on delete cascade,
  channel_id            uuid        not null references channels (id) on delete cascade,

  last_read_message_id  uuid,
  last_read_at          timestamptz not null default now(),

  -- Mutes a channel: it still shows unread state but is not counted toward the
  -- community badge on the rail.
  muted                 boolean     not null default false,

  primary key (user_id, channel_id)
);

-- Loading every read position for one user, which is what the sidebar needs.
create index channel_read_state_user_idx on channel_read_state (user_id);

-- ---------------------------------------------------------------------------
-- Invites
-- ---------------------------------------------------------------------------
--
-- A community's `join_code` is permanent and cannot be withdrawn, which makes
-- it unsuitable for inviting one person to one conversation. An invite is the
-- revocable, expiring, optionally use-limited alternative.
--
-- Uses are counted rather than recorded per user: who joined is already in
-- `community_members`, and the audit log records the invite that let them in.

create table community_invites (
  id            uuid        primary key,
  community_id  uuid        not null references communities (id) on delete cascade,

  -- Short, URL-safe, and unique across all communities so one code resolves to
  -- exactly one invite without the client naming the community first.
  code          text        not null,

  created_by    uuid        not null references users (id) on delete restrict,

  -- Null means "never expires" / "unlimited uses". Both are deliberate
  -- defaults for a small community, and both are visible in the UI.
  expires_at    timestamptz,
  max_uses      integer,

  uses          integer     not null default 0,
  revoked_at    timestamptz,

  created_at    timestamptz not null default now(),

  constraint community_invites_code_length check (char_length(code) between 6 and 32),
  constraint community_invites_code_format check (code ~ '^[A-Za-z0-9_-]+$'),
  constraint community_invites_max_uses_positive check (max_uses is null or max_uses > 0),
  constraint community_invites_uses_non_negative check (uses >= 0)
);

create unique index community_invites_code_key on community_invites (code);

-- The management list: a community's invites, newest first.
create index community_invites_community_idx on community_invites (community_id, id desc);

-- ---------------------------------------------------------------------------
-- Audit log
-- ---------------------------------------------------------------------------
--
-- Append-only. There is no update or delete path in the repository, which is
-- the point: a log an administrator can edit is not evidence of anything.
--
-- `actor_id` is nullable and `on delete set null` so removing a user does not
-- erase the record that an action happened -- `actor_label` keeps the name
-- readable afterwards. `target_id` carries no foreign key for the same reason:
-- the log must outlive the channel or invite it describes.

create table audit_log_entries (
  id            uuid        primary key,
  community_id  uuid        not null references communities (id) on delete cascade,

  actor_id      uuid        references users (id) on delete set null,
  -- Snapshot of the actor's display name at the time, so an entry stays
  -- readable after a rename or an account deletion.
  actor_label   text        not null,

  action        text        not null,

  target_type   text        not null,
  target_id     uuid,
  target_label  text,

  -- Action-specific detail, e.g. {"from":"member","to":"admin"}. Deliberately
  -- schemaless: the set of actions grows, and a column per action would not.
  metadata      jsonb       not null default '{}'::jsonb,

  created_at    timestamptz not null default now(),

  constraint audit_log_entries_action_length check (char_length(action) between 1 and 64),
  constraint audit_log_entries_target_type_length
    check (char_length(target_type) between 1 and 32),
  constraint audit_log_entries_actor_label_length
    check (char_length(actor_label) between 1 and 64),
  constraint audit_log_entries_target_label_length
    check (target_label is null or char_length(target_label) <= 128)
);

-- The only read path: one community's log, newest first, cursor-paginated by
-- id (UUIDv7, so id order is chronological).
create index audit_log_entries_community_idx on audit_log_entries (community_id, id desc);
